-- @@ comment TABLE public.ottoq_agent_prompts
COMMENT ON TABLE public.ottoq_agent_prompts IS E'0703. Every distinct system prompt an agent seat has sent, keyed by the sha256 of its text (the key must equal the database''s own hash of the stored text). Append-only. ottoq_agent_pass_evidence.prompt_sha256 names a row here by value (no FK: evidence carries no enforcing foreign keys).';
-- @@ comment INDEX public.ottoq_events_occurred_at_retention_idx
